def run_command(args,cwd):
 proc=subprocess.Popen(args,cwd=cwd,env=ENV,stdout=subprocess.PIPE,stderr=subprocess.PIPE);deadline=time.monotonic()+20;peak=0
 try:
  while proc.poll() is None:
   peak=max(peak,rss(proc.pid))
   if peak>384*1048576 or time.monotonic()>deadline:proc.kill();raise AssertionError('resource guard command')
   time.sleep(.03)
  out,err=proc.communicate();print(out.decode(errors='replace'));print(err.decode(errors='replace'))
  assert proc.returncode==0,'native command failed'
 finally:
  if proc.poll() is None:proc.kill();proc.wait(timeout=4)
  STATS.append({'kind':'promtool','peak_rss_bytes':peak,'terminated':proc.poll() is not None})
@contextlib.contextmanager
