 if live:
  config['rule_files']=[str(root/'live.yaml')]
  (root/'live.yaml').write_bytes(b'groups:\n- name: live-head-proof\n  interval: 1s\n  rules:\n  - record: service:queued_tasks:sum\n    expr: vector(999)\n    labels:\n      service: live\n')
 cfg=root/(data+'-config.yaml');cfg.write_text(yaml.safe_dump(config),encoding='utf-8')
 with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
 with (root/(data+'-server.log')).open('wb') as log:
  try:
   proc=subprocess.Popen([shutil.which('prometheus'),'--config.file='+str(cfg),'--storage.tsdb.path='+str(root/data),'--web.listen-address=127.0.0.1:'+str(port),'--log.level=error'],stdout=log,stderr=log,env=ENV,cwd=root)
   deadline=time.monotonic()+30
   def monitor():
    while not stop.wait(.1):
     if proc.poll() is not None:return
     try:
      amount=rss(proc.pid);stats['peak_rss_bytes']=max(stats['peak_rss_bytes'],amount)
      if amount>384*1048576 or time.monotonic()>deadline:fail.append('resource guard');proc.kill();return
     except Exception as exc:
      if proc.poll() is None:fail.append(str(exc));proc.kill()
      return
   guard=threading.Thread(target=monitor,daemon=True);guard.start();base='http://127.0.0.1:'+str(port)
   def api(path,params=None):
    url=base+path+('?' +urllib.parse.urlencode(params) if params else '')
    with urllib.request.urlopen(url,timeout=2) as r:
     raw=r.read();return json.loads(raw) if path.startswith('/api/') else raw
   end=time.monotonic()+6
   while True:
    try:api('/-/ready');break
    except OSError:
     assert time.monotonic()<end and proc.poll() is None;time.sleep(.05)
   yield base,api
   assert not fail,fail
  finally:
   stop.set()
   if proc is not None:
    if proc.poll() is None:proc.terminate()
    try:proc.wait(timeout=4)
    except subprocess.TimeoutExpired:proc.kill();proc.wait(timeout=4)
    stats['terminated']=proc.poll() is not None
   if guard:guard.join(timeout=2)
   STATS.append(stats)
   assert not fail,'resource guard: '+repr(fail)
def block_ids(folder):
 return sorted(p.name for p in folder.iterdir() if p.is_dir() and (p/'meta.json').is_file())
def digest_blocks(folder):
 return {str(p.relative_to(folder)):hashlib.sha256(p.read_bytes()).hexdigest() for bid in block_ids(folder) for p in (folder/bid).rglob('*') if p.is_file()}
